    session.getProvenanceReporter().fork(newFlowFile, Collections.singleton(orig));
    session.remove(orig);
    session.commit();
    final List<ProvenanceEventRecord> events = provenanceRepo.getEvents(0L, 1000);
    assertEquals(2, events.size());
