        @Override
        protected Consumer<byte[], byte[]> createKafkaConsumer() {
            return consumer;
        }
    };
    testDemarcatedPool = new ConsumerPool(1, "--demarcator--".getBytes(StandardCharsets.UTF_8), Collections.emptyMap(), Collections.singletonList("nifi"), 100L, "utf-8", "ssl", "localhost", logger) {

        @Override
        protected Consumer<byte[], byte[]> createKafkaConsumer() {
