@Test
public void validatePoolConsumerFails() throws Exception {
    when(consumer.poll(anyLong())).thenThrow(new KafkaException("oops"));
    try (final ConsumerLease lease = testPool.obtainConsumer(mockSession)) {
        try {
            lease.poll();
