    runner.disableControllerService(service);
    runner.setProperty(service, HBase_1_1_2_ClientService.HADOOP_CONF_FILES, "src/test/resources/hbase-site-security.xml, src/test/resources/core-site-security.xml");
    runner.enableControllerService(service);
    runner.assertNotValid(service);
